439	    /**
440	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
441	     * otherwise {@code 'PHONE'}.
442	     */
443	    public String getContactPreference() {
444	        return (this.email != null && !this.email.isEmpty()) ? "EMAIL" : "PHONE";
445	    }
446	
447	    /**
448	     * The owner's identity key: the single derived value used for duplicate detection.
449	     * It joins the normalized (E.164) telephone, the email (already lower-cased, or the
450	     * empty string when absent) and the householdId (or the empty string when the owner
451	     * has no household) with {@code '|'}, e.g. {@code '+61412345678|jane@example.test|3C1A9F2B7D4E'}.
452	     * Two owners are duplicates only when their whole identity keys are equal.
453	     */
454	    public String getIdentityKey() {
455	        String telephonePart = this.telephone == null ? "" : this.telephone;
456	        String emailPart = this.email == null ? "" : this.email;
457	        String householdPart = this.householdId == null ? "" : this.householdId;
458	        return telephonePart + "|" + emailPart + "|" + householdPart;
459	    }
