497	    /**
498	     * Return the Pet with the given name, or null if none found for this Owner.
499	     *
500	     * @param name to test
501	     * @return true if pet name is already in use
502	     */
503	    public Pet getPet(String name, boolean ignoreNew) {
504	        name = name.toLowerCase();
505	        for (Pet pet : getPetsInternal()) {
506	            if (!ignoreNew || !pet.isNew()) {
507	                String compName = pet.getName();
508	                compName = compName.toLowerCase();
509	                if (compName.equals(name)) {
510	                    return pet;
511	                }
512	            }
513	        }
514	        return null;
515	    }
